/// Task 1:
/// Given a non-empty Vec<DType>, returns an element of the Vec
/// whose precedence is maximal. Panics if `types` is empty.
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    assert!(!types.is_empty(), "Input vector must be non-empty");
    types
        .into_iter()
        .max_by_key(|dt| dt.precedence())
        .unwrap()
}

/// Task 2:
/// Given two Vec<DType> (array_types and scalar_types), returns
/// the common dtype according to the rules:
///  - If both are empty, returns None.
///  - If one is empty, returns the max-precedence dtype from the non-empty one.
///  - If both non-empty:
///      * compute max from each;
///      * if their kinds match, return the array max;
///      * otherwise return the scalar max.
pub fn find_common_type(
    array_types: Vec<DType>,
    scalar_types: Vec<DType>,
) -> Option<DType> {
    // If both empty, no common dtype
    if array_types.is_empty() && scalar_types.is_empty() {
        return None;
    }

    // If only array types are provided
    if scalar_types.is_empty() {
        return Some(find_max_precedence_type(array_types));
    }

    // If only scalar types are provided
    if array_types.is_empty() {
        return Some(find_max_precedence_type(scalar_types));
    }

    // Both are non-empty
    let max_array = find_max_precedence_type(array_types);
    let max_scalar = find_max_precedence_type(scalar_types);

    if max_array.kind() == max_scalar.kind() {
        Some(max_array)
    } else {
        Some(max_scalar)
    }
}